import React from 'react';
import { motion, type HTMLMotionProps } from 'framer-motion';
import clsx from 'clsx';
import './AcidButton.css';

export interface AcidButtonProps extends HTMLMotionProps<"button"> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'outline' | 'brand';
  size?: 'sm' | 'md' | 'lg';
}

export const AcidButton = React.forwardRef<HTMLButtonElement, AcidButtonProps>(
  ({ className, variant = 'primary', size = 'md', children, ...props }, ref) => {
    return (
      <motion.button
        ref={ref}
        whileTap={{ scale: 0.98 }}
        className={clsx(
          'ac-button',
          `ac-btn-${variant}`,
          `ac-btn-size-${size}`,
          className
        )}
        {...props}
      >
        <span className="ac-btn-text">{children as React.ReactNode}</span>
      </motion.button>
    );
  }
);

.ac-button {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-inter);
    font-weight: 500;
    text-transform: none;
    letter-spacing: 0;
    border: none;
    cursor: pointer;
    transition: all 0.15s ease;
    overflow: visible;
    z-index: 1;
    background: transparent;
    outline: none;
}

/* Sizes */
.ac-btn-size-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.75rem;
}

.ac-btn-size-md {
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
}

.ac-btn-size-lg {
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
}

/* Primary */
.ac-btn-primary {
    background-color: var(--ac-text-primary);
    color: var(--ac-bg);
    border: 1px solid var(--ac-text-primary);
}

.ac-btn-primary:hover {
    background-color: transparent;
    color: var(--ac-text-primary);
}

.ac-btn-primary:focus-visible {
    box-shadow: 0 0 0 2px var(--ac-bg), 0 0 0 4px var(--ac-text-primary);
}

/* Secondary */
.ac-btn-secondary {
    background-color: var(--ac-surface);
    color: var(--ac-text-primary);
    border: 1px solid var(--ac-border-bright);
}

.ac-btn-secondary:hover {
    background-color: var(--ac-border-muted);
    border-color: var(--ac-text-muted);
}

/* Ghost */
.ac-btn-ghost {
    background-color: transparent;
    color: var(--ac-text-primary);
    border: 1px solid transparent;
}

.ac-btn-ghost:hover {
    background-color: var(--ac-surface-hover);
    border-color: var(--ac-border-muted);
}

/* Outline */
.ac-btn-outline {
    background-color: transparent;
    color: var(--ac-text-primary);
    border: 1px solid var(--ac-border-muted);
}

.ac-btn-outline:hover {
    background-color: var(--ac-text-primary);
    color: var(--ac-bg);
}

/* Brand */
.ac-btn-brand {
    background-color: var(--ac-brand);
    color: var(--ac-bg);
    border: 1px solid var(--ac-brand);
}

.ac-btn-brand:hover {
    background-color: transparent;
    color: var(--ac-brand);
}
